def _has(rel):
    return rel if rel and os.path.exists(os.path.join(_ROOT, rel)) else None
def P(id, name, qa, note, user="", defect="—", deck=True, b1440=True, b390=True, spec=None, dev="—"):
    d = {"id": id, "name": name, "qa": qa, "note": note, "user": user, "defect": defect, "dev": dev,
         "deck": _has(f"deck/{id}.jpg") if deck is True else deck,
         "b1440": _has(f"v3/{id}-1440.jpg") if b1440 is True else _has(b1440) if b1440 else None,
         "b390": _has(f"v3/{id}-390.jpg") if b390 is True else _has(b390) if b390 else None}
    if spec: d["spec"] = spec; d["deck_empty"] = "Spec only (no crop)"
    return d
